export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "10:30。東京都防災學習館附設研修資料室。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "這裡不像祕密檔案館。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "樓下傳來小學生的聲音。防災模型展示區。地震體驗。有人在大廳裡排隊。二樓研修資料室的門隔開了那些聲音，但沒有完全擋住。日光燈嗡嗡地亮著。金屬架上整齊排列著盒裝資料——盒脊上貼著標籤。退役研修教材。舊版維護手冊。盒裝光碟。紙本目錄抽屜沿牆排開。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "一個館員坐在櫃台後面。旁邊有一台舊型錄影機和一疊退役設備清單。牆上貼著閱覽規則——館內閱覽。不帶離。不拆釘。可拍攝頁面需由館員確認。端點、帳號、金鑰與安全操作細節以替代頁處理。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯公共設施。半公共。週六開放。學校團體在樓下。退役設備展示在走廊。這裡不是 TKS 的內部資料室。是防災學習館的附設研修資料室。退役型號的舊教材。低風險歷史資料。任何人都可以預約。只是需要提前申請。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看著面前兩個牛皮紙盒。第一個盒子——退役研修教材。第二個盒子——離線復舊程序手冊。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她先打開第一個盒子。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "裡面是幾張紙本講義和一疊裝在透明套裡的投影片。投影片是列印輸出的。A4 大小。黑白。等寬字體。每一頁右下角有頁碼。左上角有交付編號。右上角有改訂日期。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "盒內附有一張館藏登錄卡。卡上寫著——資料包編號。送存日期。退役標記。型號名稱。保管單位。閱覽級別——低風險歷史資料（館內閱覽）。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯先記錄館藏登錄卡。資料包編號。送存日期。退役標記。這些把整盒東西固定在一個時間和一個程序裡。不是網頁。不是快取。是有人送存、有人登記、有人放在這裡的。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她在筆記本上抄下館藏登錄卡的資訊。然後開始逐釐翻投影片。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "前面幾頁是普通的研修教材概論。TKS-SYNC 系統簡介。同步群的概念。多通道測試的基本流程。都是她已經從公開文件裡見過的東西。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她一頁一頁翻。頁碼遞增。改訂日期一致。交付編號一致。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "10:48。她翻到一頁。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "投影片標題——設定檔名稱與維護別名對照（研修用）。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的手指停在頁面邊緣。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "頁面上有一個表格。五行。五欄。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第一欄——公開設定名。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第二欄——維護別名。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第三欄——狀態。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第四欄——來源。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第五欄——用途。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "第一行。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "公開設定名——TOKYO。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "維護別名——TOKYO-7。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "狀態——退役舊版／研修鏡像。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "來源——實際運用環境舊版匯出。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "用途——另見目的記述書。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯TOKYO-7。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的手指壓在那一行上。沒有動。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯TOKYO-7。維護別名。不是公開設定名。是維護別名。公開設定名是 TOKYO。維護別名是 TOKYO-7。狀態是退役舊版。來源——實際運用環境舊版匯出。用途——另見目的記述書。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯實際運用環境舊版匯出。不是「研修用虛構範例」。不是「教學示例」。是——從實際運用環境的舊版匯出來的。這個名字曾經在實際運用環境裡使用過。它不是教學人員隨便編的。它是從真實系統裡匯出來的。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她沒有立刻拍照。她先把整頁從頭到尾看了一遍。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "頁面頂端有投影片標題。標題下面有表格。表格有五行——但只有第一行寫了 TOKYO 和 TOKYO-7。其他幾行是其他設定檔的別名對照。有些被遮蔽了。有些標著「已廢止」。只有第一行是完整的。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "頁面右下角——頁碼。第 14 頁。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "左上角——交付編號。與盒上的交付編號一致。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "右上角——改訂日期。在星期一灣岸測試之前。在悠真失蹤之前。在千田死亡之前。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "頁面底部有一行小字——研修鏡像由實際運用環境舊版複製，僅供離線復舊程序訓練使用。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯改訂日期。在事件之前。這份投影片在星期一之前就改訂了。在悠真失蹤之前。在千田死亡之前。在 TKS 收到媒體詢問之前。它不是事後補的。不是因為有人在查才放的。它在那裡。在所有人開始調查之前就在那裡。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯不跳。不跳到結論。先記錄。整頁。頁碼。交付編號。改訂日期。標題。表格。五行五欄。第一行——TOKYO。TOKYO-7。退役舊版／研修鏡像。實際運用環境舊版匯出。另見目的記述書。底部小字。全部抄下來。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她叫館員過來。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "請問這一頁可以拍了嗎？", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.ArchiveStaff, character: "資料室職員", dialogue: "讓我確認一下。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "館員走過來。看了一下投影片。翻看了一下透明套。確認沒有被拆釘。確認頁面完整。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.ArchiveStaff, character: "資料室職員", dialogue: "這頁沒有端點或帳號資訊，可以拍。拍的時候要拍完整頁面，包括頁碼和交付編號。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "好。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她拿起手機。拍。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她不只拍 TOKYO-7 那一格。她拍整頁。投影片標題。完整表格。五行五欄。頁碼。交付編號。改訂日期。底部小字。館藏登錄卡。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "拍完之後，她在筆記本上逐欄抄錄。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "公開設定名——TOKYO。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "維護別名——TOKYO-7。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "狀態——退役舊版／研修鏡像。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "來源——實際運用環境舊版匯出。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "用途——另見目的記述書。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "頁碼——第 14 頁。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "交付編號——抄。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "改訂日期——抄。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯用途欄寫的是「另見目的記述書」。不是「災害警報」。不是「多通道測試」。不是「地域配置」。是——另見目的記述書。這表示 TOKYO-7 的用途不在這頁上。在另一份文件裡。一份叫「目的記述書」的文件。這份投影片只告訴我名字和來源。不告訴我用途。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她繼續翻。投影片往後幾頁是離線復舊程序的概論。她先不看那些。她回到盒子裡，翻找同一交付包裡的其他文件。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "盒底有另一份紙本。不是投影片。是一張裝訂過的紀錄表。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "表頭——回復檢查紀錄。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "同一交付編號。同一改訂日期。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她翻到紀錄表的第一頁。逐行看。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "10:58。她看見一行。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "紀錄表上寫著——實際運用設定 TOKYO-7 已複製至研修鏡像，用於離線復舊程序訓練。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯第二個來源。同一交付包。同一交付編號。同一改訂日期。回復檢查紀錄。不是投影片。是另一種文件。它寫的是——實際運用設定 TOKYO-7 已複製至研修鏡像。用於離線復舊程序訓練。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯「實際運用設定 TOKYO-7」。不是「研修範例 TOKYO-7」。不是「教學用 TOKYO-7」。是——實際運用設定。這份紀錄表把它叫作實際運用設定。它被複製到研修鏡像。用於訓練。所以投影片上的「來源——實際運用環境舊版匯出」不是隨便寫的。回復檢查紀錄獨立確認了這件事。兩個來源。同一交付包。同一編號。同一日期。互相支撐。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她叫館員。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "這份紀錄表也可以拍嗎？", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.ArchiveStaff, character: "資料室職員", dialogue: "我看看。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "館員翻看紀錄表。確認沒有端點、帳號或金鑰資訊。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.ArchiveStaff, character: "資料室職員", dialogue: "可以。整頁拍。包括表頭和編號。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她拍。整頁。表頭。交付編號。改訂日期。那一行——實際運用設定 TOKYO-7 已複製至研修鏡像，用於離線復舊程序訓練。頁碼。裝訂戳。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "拍完之後，她在筆記本上抄下這行字。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "抄完。她放下筆。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:05。她靠回椅背。看著筆記本上抄的東西。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "樓下傳來小學生的笑聲。很遠。很普通。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯千田。第一輪。車廂裡。他說——不要救東京。他沒有說不要救 TOKYO。他沒有說不要救 TOKYO-7。他說的是——東京。中文裡的東京。日本語裡的東京。兩個字。不是設定檔名稱。不是維護別名。是一個城市的名字。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯但現在。在這張投影片上。在這份回復檢查紀錄上。「東京」被寫成了一個有版本的東西。TOKYO。TOKYO-7。退役舊版。實際運用環境舊版匯出。另見目的記述書。它不是城市。在這些文件裡——它是一個設定檔。一個有維護別名的設定檔。一個從實際運用環境匯出來的設定檔。一個有用途、但用途寫在另一份不公開文件裡的設定檔。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Shocked },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯千田臨死前說的「東京」——是城市嗎。還是設定檔。還是——兩者都是。他說「不要救東京」。如果東京是一個設定檔——「不要救」是什麼意思。不要恢復它。不要啟用它。不要讓它被回復到現場控制台。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Sad },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯不跳。不能跳。我現在有的東西是——TOKYO-7 這個名字存在。它出現在退役研修教材裡。它出現在回復檢查紀錄裡。兩個來源。同一交付包。改訂日期在事件之前。來源標注為實際運用環境舊版匯出。這些是能確認的。其他的——它的用途。它和 G07 的關係。它和千田的關係。它和悠真的關係——都不能確認。不能跳。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她坐直。拿起筆。翻到筆記本新的一頁。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她沒有寫長段的分析。她只寫了一行。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "TOKYO-7：存在。用途未知。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯就這樣。一行。存在。用途未知。不寫「千田說的東京就是這個」。不寫「TOKYO-7 就是東京方案」。不寫「-7 等於 G07」。只寫——存在。用途未知。這是今天能確認的。最多到這裡。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看著這行字。看了很久。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:15。她繼續翻投影片。後面幾頁是離線復舊程序的流程概論。她逐頁記錄。不跳。不挑。每一頁都抄下頁碼、標題和關鍵欄位。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:35。她翻到投影片最後一頁。頁面底部有一行引用標注——本研修教材引用之設定檔用途說明，請參照「設定檔目的記述書」（限制閱覽）。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯設定檔目的記述書。限制閱覽。投影片上的用途欄寫的是「另見目的記述書」。這裡又出現了一次。同一份文件。兩處引用。它不公開。它限制閱覽。它記錄的是——設定檔為什麼存在。設定檔的用途是什麼。TOKYO-7 的用途是什麼。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯但今天拿不到。限制閱覽。不是這個資料包裡的東西。是另一份文件。需要另走程序。今天先把名字和來源記錄下來。用途——之後再追。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她在筆記本上寫——", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "設定檔目的記述書——限制閱覽。研修教材兩處引用。文件名稱確認。正文未取得。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:50。她把投影片和回復檢查紀錄整理好。放回盒裡。沒有拆釘。沒有折頁。順序跟取出時一致。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她叫館員。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "第一個盒子看完了。可以還了。第二個盒子——離線復舊程序手冊——我想下午再看。中午休息一下。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.ArchiveStaff, character: "資料室職員", dialogue: "好的。第二個盒子可以幫您保留在指定座位。下午一點以後繼續閱覽沒問題。閉館是四點半。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "好。謝謝。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她把第一個盒子交還。館員確認內容完整。在歸還紀錄上簽名。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "11:58。澪站起來。收好筆記本。收好手機。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她走到窗邊。看了一眼外面。樓下的廣場上有幾個小學生在吃便當。防災學習館的旗幟在風裡微微動著。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）⋯⋯悠真。失蹤第十二日。我不知道你在哪裡。我不知道 G07 裡面有沒有你。我只知道——有一個叫 TOKYO-7 的東西。它存在。它從實際運用環境匯出。它的用途寫在一份我還看不到的文件裡。千田說不要救東京。我不知道他說的東京是不是這個。但我現在知道——「東京」在這些文件裡不是城市。是一個有版本的名字。", background: Background.Chapter_15_Ch15_Act2_S0, portrait: Portrait.AsakuraMio_Sad },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "12:05。她走出研修資料室。下樓。穿過大廳。小學生的聲音在背後漸漸變遠。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她走到館外的長椅上坐下。打開背包。拿出筆記本。翻到剛才寫的那一行。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "TOKYO-7：存在。用途未知。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她看著這行字。旁邊是防災學習館的灰色建築。裡面有防災模型。有退役設備。有學校團體。有盒裝光碟。有紙本目錄。有一頁投影片。上面印著一個沒有公開的名字。", background: Background.Chapter_15_Ch15_Act2_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "那個名字在她看見之前就已經印在那裡了。", background: Background.Chapter_15_Ch15_Act2_S0 },
];
